def generate_pivot_sql(category_col: str, categories: list, measure_col: str) -> str:
    cases = [
        f"SUM(CASE WHEN {category_col} = '{cat}' THEN {measure_col} ELSE 0 END) AS {cat}_total"
        for cat in categories
    ]
    return ",\n".join(cases)

